{params.status && (
  <button onClick={() => onChange({ status: undefined })}
    className="text-xs text-primary hover:underline text-left mt-1">
    Clear
  </button>
)}

{(params.status || params.department || params.category) && (
  <button onClick={() => onChange({ status: undefined, department: undefined, category: undefined })}
    className="text-xs text-red-400 hover:underline text-left">
    Reset all filters
  </button>
)}

{mode === 'edit' && tool && (
  <ToolForm
    defaultValues={tool}
    onSubmit={values => updateTool.mutate({ id: tool.id, data: values })}
    isLoading={updateTool.isPending}
    onCancel={onClose}
  />
)}

{mode === 'delete' && tool && (
  <div className="flex flex-col gap-4">
    <p className="text-sm text-gray-500">Supprimer <strong>{tool.name}</strong> ? Cette action est irréversible.</p>
    <div className="flex gap-2 justify-end">
      <button onClick={onClose} className="px-4 py-2 rounded-lg border text-sm hover:bg-gray-50 dark:hover:bg-gray-700">Annuler</button>
      <button onClick={() => deleteTool.mutate(tool.id)} disabled={deleteTool.isPending}
        className="px-4 py-2 rounded-lg bg-red-500 text-white text-sm hover:bg-red-600 disabled:opacity-50">
        {deleteTool.isPending ? 'Suppression...' : 'Supprimer'}
      </button>
    </div>
  </div>
)}

export const useCreateTool = (onSuccess?: () => void) => {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: (data: Partial<Tool>) => toolMutations.create(data),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ['tools'] }); onSuccess?.() }
  })
}

const createTool = useCreateTool(onClose)
const updateTool = useUpdateTool(onClose)
const deleteTool = useDeleteTool(onClose)

return useMutation({
  mutationFn: (data: Partial<Tool>) => toolMutations.create(data),
  onSuccess: () => { qc.invalidateQueries({ queryKey: ['tools'] }); onSuccess?.() }
  // NO onError callback
})

const Field = ({ label, error, children }) => (
  <div className="flex flex-col gap-1">
    <label className="text-xs font-medium text-gray-500">{label}</label>
    {children}
    {error && <p className="text-xs text-red-500">{error}</p>}
  </div>
)
